        <see cref = 'grafana.updatePlaylistResponse'/> playlists
        <see cref = 'grafana.updateProviderSettingsReq'/> sso_settings
        <see cref = 'grafana.updatePublicDashboardReq'/> dashboard_public | dashboards
        <see cref = 'grafana.updatePublicDashboardResponse'/> dashboard_public | dashboards
        <see cref = 'grafana.updateReportReq'/> enterprise | reports
        <see cref = 'grafana.updateRoleReq'/> access_control | enterprise
        <see cref = 'grafana.updateServiceAccountReq'/> service_accounts
        <see cref = 'grafana.updateServiceAccountResponse'/> service_accounts
        <see cref = 'grafana.updateTeamLBACRulesApiReq'/> enterprise
        <see cref = 'grafana.updateTeamLBACRulesResponse'/> enterprise
        <see cref = 'grafana.updateTeamMemberReq'/> teams
        <see cref = 'grafana.updateTeamPreferencesReq'/> preferences | teams
        <see cref = 'grafana.updateTeamReq'/> teams
        <see cref = 'grafana.updateUserQuotaReq'/> admin_users | quota
        <see cref = 'grafana.updateUserReq'/> users
        <see cref = 'grafana.uploadSnapshotReq'/> migrations
        <see cref = 'grafana.userResponse'/> signed_in_user | users
