    [Title(@"Grafana HTTP API.")]
    [Version(@"0.0.1")]
    [Description(@"The Grafana backend exposes an HTTP API, the same API is used by the frontend to do
everything from saving dashboards, creating users and updating data sources.")]
    [Contact(@"Grafana Labs", @"hello@grafana.com", @"https://grafana.com/")]
    [TagDefinition(@"datasources", @"If you are running Grafana Enterprise and have Fine-grained access control enabled, for some endpoints you would need to have relevant permissions. Refer to specific resources to understand what permissions are required.", @"", @"", @"")]
    [TagDefinition(@"folders", @"Folders are identified by the identifier (id) and the unique identifier (uid).
The identifier (id) of a folder is an auto-incrementing numeric value and is only unique per Grafana install.
The unique identifier (uid) of a folder can be used for uniquely identify folders between multiple Grafana installs. It’s automatically generated if not provided when creating a folder. The uid allows having consistent URLs for accessing folders and when syncing folders between multiple Grafana installs. This means that changing the title of a folder will not break any bookmarked links to that folder.
The uid can have a maximum length of 40 characters.", @"", @"", @"")]
    [TagDefinition(@"permissions", @"Permissions with `folderId=-1` are the default permissions for users with the Viewer and Editor roles. Permissions can be set for a user, a team or a role (Viewer or Editor). Permissions cannot be set for Admins - they always have access to everything.", @"", @"", @"")]
    [TagDefinition(@"admin", @"The Admin HTTP API does not currently work with an API Token. API Tokens are currently only linked to an organization and an organization role. They cannot be given the permission of server admin, only users can be given that permission. So in order to use these API calls you will have to use Basic Auth and the Grafana user must have the Grafana Admin permission. (The default admin user is called admin and has permission to use this API.)", @"", @"", @"")]
    [TagDefinition(@"annotations", @"Grafana Annotations feature released in Grafana 4.6. Annotations are saved in the Grafana database (sqlite, mysql or postgres). Annotations can be organization annotations that can be shown on any dashboard by configuring an annotation data source - they are filtered by tags. Or they can be tied to a panel on a dashboard and are then only shown on that panel.", @"", @"", @"")]
    [TagDefinition(@"library_elements", @"The identifier (ID) of a library element is an auto-incrementing numeric value that is unique per Grafana install.
The unique identifier (UID) of a library element uniquely identifies library elements between multiple Grafana installs. It’s automatically generated unless you specify it during library element creation. The UID provides consistent URLs for accessing library elements and when syncing library elements between multiple Grafana installs.
The maximum length of a UID is 40 characters.", @"", @"", @"")]
    [TagDefinition(@"query_history", @"The identifier (ID) of a query in query history is an auto-incrementing numeric value that is unique per Grafana install.
The unique identifier (UID) of a query history uniquely identifies queries in query history between multiple Grafana installs. It’s automatically generated. The UID provides consistent URLs for accessing queries in query history.", @"", @"", @"")]
    [TagDefinition(@"orgs", @"The Admin Organizations HTTP API does not currently work with an API Token. API Tokens are currently only linked to an organization and an organization role. They cannot be given the permission of server admin, only users can be given that permission. So in order to use these API calls you will have to use Basic Auth and the Grafana user must have the Grafana Admin permission (The default admin user is called `admin` and has permission to use this API).", @"", @"", @"")]
    [TagDefinition(@"org", @"If you are running Grafana Enterprise and have Fine-grained access control enabled, for some endpoints you would need to have relevant permissions. Refer to specific resources to understand what permissions are required.", @"", @"", @"")]
    [TagDefinition(@"teams", @"This API can be used to create/update/delete Teams and to add/remove users to Teams. All actions require that the user has the Admin role for the organization.", @"", @"", @"")]
    [TagDefinition(@"enterprise", @"These are only available in Grafana Enterprise", @"", @"", @"")]
    [TagDefinition(@"access_control", @"The API can be used to create, update, get and list roles, and create or remove built-in role assignments. To use the API, you would need to enable fine-grained access control.
This only available in Grafana Enterprise.
The API does not currently work with an API Token. So in order to use these API endpoints you will have to use Basic auth.", @"", @"", @"")]
    [TagDefinition(@"licensing", @"Licensing is only available in Grafana Enterprise. Read more about Grafana Enterprise.
If you are running Grafana Enterprise and have Fine-grained access control enabled, for some endpoints you would need to have relevant permissions. Refer to specific resources to understand what permissions are required.", @"", @"", @"")]
    [TagDefinition(@"reports", @"This API allows you to interact programmatically with the Reporting feature.
Reporting is only available in Grafana Enterprise. Read more about Grafana Enterprise.
If you have Fine-grained access Control enabled, for some endpoints you would need to have relevant permissions. Refer to specific resources to understand what permissions are required.", @"", @"", @"")]
    [TagDefinition(@"service_accounts", @"If you are running Grafana Enterprise, for some endpoints you'll need to have specific permissions. Refer to [Role-based access control permissions](https://grafana.com/docs/grafana/latest/administration/roles-and-permissions/access-control/custom-role-actions-scopes/) for more information.", @"", @"", @"")]
    public interface grafana {
        // 64-bit integers are `long` / `ulong` here, as `format: int64` says. A JSON number goes through a
        // double in JavaScript, so values above 2^53 never arrived there intact: if TypeScript hosts
        // matter and the values stay below that, `longJS` / `ulongJS` are the cheaper types.
        //
        // The document states ranges, never distributions. Where the values of an integer cluster - a
        // counter near its floor, a budget near its ceiling, a delta around zero - [A], [V] or [X] on
        // that field is the most valuable edit after conversion.

        // Caps for collections that carry no explicit [D(...)] attribute. JSON APIs rarely declare bounds,
        // so these permissive defaults replace AdHoc's own limit of 255 items/chars. Put [D(+N)] on a
        // field whose real bound is known and tighten the rest.
        enum _DefaultMaxLengthOf { Arrays = 65_535, Maps = 65_535, Sets = 65_535, Strings = 65_535, }

        /// <summary>
        /// Synthetic pack representing an empty request or response.
        /// Used when an operation has no parameters or body.
        /// </summary>
        public class NoArg { }

        /// <summary>Shared error pack set - error schemas reused across operations.</summary>
        public interface StandardErrors : _<(Code_404, ForbiddenError, PublicError, ValidationError, badRequestError, badRequestPublicError, conflictError, forbiddenError_Response, forbiddenPublicError, internalServerError, internalServerPublicError, notFoundError, notFoundPublicError, preconditionFailedError, unauthorisedError, unauthorisedPublicError, unprocessableEntityError)> { }

