        public class AlertRuleNotificationSettings {
            /// <summary>
            /// example: ["maintenance"]
            ///
            /// Override the times when notifications should not be muted. These must match the name of a mute time interval
            /// defined
            /// in the alertmanager configuration time_intervals section. All notifications will be suppressed unless they are
            /// sent
            /// at the time that matches any interval.
            /// </summary>
            string[,,]? active_time_intervals;

            /// <summary>
            /// example: ["alertname","grafana_folder","cluster"]
            ///
            /// Override the labels by which incoming alerts are grouped together. For example, multiple alerts coming in for
            /// cluster=A and alertname=LatencyHigh would be batched into a single group. To aggregate by all possible labels
            /// use the special value '...' as the sole label name.
            /// This effectively disables aggregation entirely, passing through all alerts as-is. This is unlikely to be what
            /// you want, unless you have a very low alert volume or your upstream notification system performs its own
            /// grouping.
            /// Must include 'alertname' and 'grafana_folder' if not using '...'.
            /// </summary>
            string[,,]? group_by;

            /// <summary>
            /// example: 5m
            ///
            /// Override how long to wait before sending a notification about new alerts that are added to a group of alerts
            /// for
            /// which an initial notification has already been sent. (Usually ~5m or more.)
            /// </summary>
            string? group_interval;

            /// <summary>
            /// example: 30s
            ///
            /// Override how long to initially wait to send a notification for a group of alerts. Allows to wait for an
            /// inhibiting alert to arrive or collect more initial alerts for the same group. (Usually ~0s to few minutes.)
            /// </summary>
            string? group_wait;

            /// <summary>
            /// example: ["maintenance"]
            ///
            /// Override the times when notifications should be muted. These must match the name of a mute time interval
            /// defined
            /// in the alertmanager configuration time_intervals section. When muted it will not send any notifications, but
            /// otherwise acts normally.
            /// </summary>
            string[,,]? mute_time_intervals;

            /// <summary>
            /// example: "Alerting Team"
            ///
            /// Name of the notification policy to route alerts through.
            /// Mutually exclusive with all other fields, cannot be used with contact point routing via the "receiver" field.
            /// </summary>
            string? policy;

            /// <summary>
            /// example: grafana-default-email
            ///
            /// Name of the receiver to send notifications to.
            /// </summary>
            string receiver;

            /// <summary>
            /// example: 4h
            ///
            /// Override how long to wait before sending a notification again if it has already been sent successfully for an
            /// alert. (Usually ~3h or more).
            /// Note that this parameter is implicitly bound by Alertmanager's `--data.retention` configuration flag.
            /// Notifications will be resent after either repeat_interval or the data retention period have passed, whichever
            /// occurs first. `repeat_interval` should not be less than `group_interval`.
            /// </summary>
            string? repeat_interval;
        }

