        /// <summary>
        /// Config defines the internal representation of a cache configuration, including fields not set by the API
        /// caller
        /// </summary>
        public class CacheConfig {
            DateTime? created;

            /// <summary>Fields that can be set by the API caller - read/write</summary>
            long? dataSourceID;
            string? dataSourceUID;

            /// <summary>
            /// These are returned by the HTTP API, but are managed internally - read-only
            /// Note: 'created' and 'updated' are special properties managed automatically by xorm, but we are setting them
