        /// <summary>
        /// TITLE: QueryStat is used for storing arbitrary statistics metadata related to a query and its result, e.g.
        /// total request time, data processing time.
        /// The embedded FieldConfig's display name must be set.
        /// It corresponds to the QueryResultMetaStat on the frontend
        /// (https://github.com/grafana/grafana/blob/master/packages/grafana-data/src/types/data.ts#L53).
        /// </summary>
        public class QueryStat {
            /// <summary>
            /// Map values to a display color
            /// NOTE: this interface is under development in the frontend... so simple map for now
            /// </summary>
            Map<string, Binary[,,]>? color; // any JSON in the spec: carried as raw bytes

            /// <summary>Panel Specific Values</summary>
            Map<string, Binary[,,]>? custom; // any JSON in the spec: carried as raw bytes
            ushort? decimals;

            /// <summary>Description is human readable field metadata</summary>
            string? description;

            /// <summary>DisplayName overrides Grafana default naming, should not be used from a data source</summary>
            string? displayName;

            /// <summary>DisplayNameFromDS overrides Grafana default naming strategy.</summary>
            string? displayNameFromDS;

            /// <summary>Filterable indicates if the Field's data can be filtered by additional calls.</summary>
            bool? filterable;

            /// <summary>
            /// Interval indicates the expected regular step between values in the series.
            /// When an interval exists, consumers can identify "missing" values when the expected value is not present.
            /// The grafana timeseries visualization will render disconnected values when missing values are found it the time
            /// field.
            /// The interval uses the same units as the values.  For time.Time, this is defined in milliseconds.
            /// </summary>
            double? interval;

            /// <summary>The behavior when clicking on a result</summary>
            DataLink[,,]? links;
            ValueMappings? mappings;
            ConfFloat64? max;
            ConfFloat64? min;

            /// <summary>Alternative to empty string</summary>
            string? noValue;

            /// <summary>
            /// Path is an explicit path to the field in the datasource. When the frame meta includes a path,
            /// this will default to `${frame.meta.path}/${field.name}
            ///
            /// When defined, this value can be used as an identifier within the datasource scope, and
            /// may be used as an identifier to update values in a subsequent request
            /// </summary>
            string? path;
            ThresholdsConfig? thresholds;
            FieldTypeConfig? Type;

            /// <summary>Numeric Options</summary>
            string? unit;
            double? value;

            /// <summary>Writeable indicates that the datasource knows how to update this value</summary>
            bool? writeable;
        }

