        interface ClientServerConnection : Connects<Client, Server> {
            // /access-control
            public interface access_control {
                public interface roles {
                    /// <summary>
                    /// Get all roles.
                    /// Gets all existing roles. The response contains all global and organization local roles, for the organization
                    /// which user is signed in.
                    ///
                    /// You need to have a permission with action `roles:read` and scope `roles:*`.
                    ///
                    /// The `delegatable` flag reduces the set of roles to only those for which the signed-in user has permissions to
                    /// assign.
                    /// tags: access_control, enterprise
                    /// </summary>
                    [HttpMethod(@"GET")]
                    [Tag(@"access_control", @"The API can be used to create, update, get and list roles, and create or remove built-in role assignments. To use the API, you would need to enable fine-grained access control.
This only available in Grafana Enterprise.
The API does not currently work with an API Token. So in order to use these API endpoints you will have to use Basic auth.")]
                    [Tag(@"enterprise", @"These are only available in Grafana Enterprise")]
                    (L____________,
                        listRolesResponse,
                        /// <summary>shared errors</summary>
                        StandardErrors) listRoles(listRolesReq req);

                    /// <summary>
                    /// Create a new custom role.
                    /// Creates a new custom role and maps given permissions to that role. Note that roles with the same prefix as
                    /// Fixed Roles can’t be created.
                    ///
                    /// You need to have a permission with action `roles:write` and scope `permissions:type:delegate`.
                    /// `permissions:type:delegate` scope ensures that users can only create custom roles with the same, or a subset
                    /// of permissions which the user has.
                    /// For example, if a user does not have required permissions for creating users, they won’t be able to create a
                    /// custom role which allows to do that. This is done to prevent escalation of privileges.
                    /// tags: access_control, enterprise
                    /// </summary>
                    [HttpMethod(@"POST")]
                    [Tag(@"access_control", @"The API can be used to create, update, get and list roles, and create or remove built-in role assignments. To use the API, you would need to enable fine-grained access control.
This only available in Grafana Enterprise.
The API does not currently work with an API Token. So in order to use these API endpoints you will have to use Basic auth.")]
                    [Tag(@"enterprise", @"These are only available in Grafana Enterprise")]
                    (L____________,
                        createRoleResponse,
                        /// <summary>shared errors</summary>
                        StandardErrors) createRole(CreateRoleForm req);

                    // /access-control/roles/{roleUID}
                    public interface roleUID {
                        /// <summary>
                        /// Delete a custom role.
                        /// Delete a role with the given UID, and it’s permissions. If the role is assigned to a built-in role, the
                        /// deletion operation will fail, unless force query param is set to true, and in that case all assignments will
                        /// also be deleted.
                        ///
                        /// You need to have a permission with action `roles:delete` and scope `permissions:type:delegate`.
                        /// tags: access_control, enterprise
                        /// </summary>
                        [HttpMethod(@"DELETE")]
                        [Tag(@"access_control", @"The API can be used to create, update, get and list roles, and create or remove built-in role assignments. To use the API, you would need to enable fine-grained access control.
This only available in Grafana Enterprise.
The API does not currently work with an API Token. So in order to use these API endpoints you will have to use Basic auth.")]
                        [Tag(@"enterprise", @"These are only available in Grafana Enterprise")]
                        (L____________,
                            /// <summary>An OKResponse is returned if the request was successful.</summary>
                            okResponse,
                            /// <summary>shared errors</summary>
                            StandardErrors) deleteRole(deleteRoleReq req);

                        /// <summary>
                        /// Get a role.
                        /// Get a role for the given UID.
                        ///
                        /// You need to have a permission with action `roles:read` and scope `roles:*`.
                        /// tags: access_control, enterprise
                        /// </summary>
                        [HttpMethod(@"GET")]
                        [Tag(@"access_control", @"The API can be used to create, update, get and list roles, and create or remove built-in role assignments. To use the API, you would need to enable fine-grained access control.
This only available in Grafana Enterprise.
The API does not currently work with an API Token. So in order to use these API endpoints you will have to use Basic auth.")]
                        [Tag(@"enterprise", @"These are only available in Grafana Enterprise")]
